entries[27602] = { ["name"] = "Arkanitdrachling beschwören", ["text"] = "Sofort 1 Stunde Abklingzeit\nDer Arkanitdrachling erwacht zum Leben und verteidigt Euch 1 Min. lang." }
entries[27603] = { ["name"] = "Goblindrachengewehr", ["text"] = "Kanalisiert (Wirken in 8 sek.)\nFügt jedem Feind in einem kegelförmigen Bereich vor dem Ingenieur, der die Waffe benutzt, 8 Sek. lang 3 Feuerschaden zu. Es sei denn, sie explodiert..." }
entries[27604] = { ["name"] = "Goblindrachengewehr", ["text"] = "Sofort\nFügt allen Zielen in einem kegelförmigen Bereich vor dem die Waffe abfeuernden Ingenieur 8 Sek. lang 3 Feuerschaden zu - zumindest, solange die Waffe nicht explodiert..." }
entries[27605] = { ["name"] = "Schattenwort: Schmerz", ["text"] = "470 Mana 30 Meter Reichweite\nSofort\nEin Wort der Dunkelheit, das 18 Sek. lang insgesamt (100.2% der Zaubermacht) Schattenschaden zufügt." }
entries[27606] = { ["name"] = "Erneuerung", ["text"] = "365 Mana 40 Meter Reichweite\nSofort\nHeilt das Ziel 15 Sek. lang um (100% der Zaubermacht) Schaden." }
entries[27607] = { ["name"] = "Machtwort: Schild", ["text"] = "500 Mana 40 Meter Reichweite\nSofort 4 sek. Abklingzeit\nNutzt die Seelenkraft des Gruppenmitglieds zum Abschirmen und absorbiert dabei 11 Schaden. Hält 30 Sek. lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 7.5 Sek. lang nicht wieder abgeschirmt werden." }
entries[27608] = { ["name"] = "Blitzheilung", ["text"] = "380 Mana 40 Meter Reichweite\nWirken in 1.5 sek.\nHeilt ein verbündetes Ziel um (42.9% der Zaubermacht) Gesundheit." }
