entries[27619] = { ["name"] = "Eisblock", ["text"] = "Sofort 5 min Abklingzeit\nIhr werdet in einen Eisblock eingehüllt, der Euch 6 Sek. lang vor allen körperlichen Angriffen und Zaubern schützt, allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen und auch keine Zauber wirken." }
