entries[27621] = { ["name"] = "Totem des Windzorns", ["text"] = "Sofort 20 sek. Abklingzeit\nBeschwört ein Totem des Windzorns zu Füßen des Zaubernden, das 1.5 Min. lang bestehen bleibt. Das Totem verzaubert alle Verbündeten innerhalb von 30 Metern, sodass jeder Treffer eine Chance von 20% hat, dem Angreifer 2 zusätzliche Angriffe zu gewähren." }
entries[27622] = { ["name"] = "Get the Key: Vaelen's Invisibility & See Invisibility" }
entries[27623] = { ["name"] = "Totem der Feuernova", ["text"] = "640 Mana\nSofort 15 sek. Abklingzeit\nBeschwört ein Totem der Feuernova mit 5 Gesundheit, das 5 Sek. lang anhält. Wenn es nicht innerhalb von 5.2 Sek. zerstört wird, fügt das Totem Feinden in einem Umkreis von 0 Metern 5 Feuerschaden zu." }
entries[27624] = { ["name"] = "Geringe Welle der Heilung", ["text"] = "380 Mana 40 Meter Reichweite\nWirken in 1.5 sek.\nHeilt ein verbündetes Ziel um (42.9% der Zaubermacht) Gesundheit." }
