entries[27632] = { ["name"] = "Gezielter Schuss", ["text"] = "310 Mana 35 Meter Reichweite\nWirken in 3 sek. 6 sek. Abklingzeit\nBenötigt Distanzwaffe\nEin gezielter Schuss, der den Distanzschaden um 1080 erhöht." }
